# The differential test of the Qt port: the same cases go to the Kotlin originals on the JVM (Oracle.java, on the jars of
# server/build/sidecar-image) and to the C++ ports (build/qt/xgs-diff.exe); the answers must be identical, line for line.
#
#   pwsh qt/tools/differential/run.ps1 [-Kinds UXMSCFDGTLYRNBZHOJEQ] [-PerKind 10000] [-Seed 20261115]   (the default: all kinds)
#
# Kinds U, X, M, B and Z have no cases: the two sides each print a table (unicodecase, chartable, constants, lettertable,
# nfkctable) and the tables are compared. Every other kind is generated by `xgs-diff gen`. The kinds are run one at a time
# and each kind's data is released before the next, so that all kinds fit in memory at -PerKind 100000. The exit code is 0 only when, for every kind, the
# answer counts match, no answer differs and the kind's statistics reach their thresholds ($Statistics below). Input and
# output are ASCII. Before anything else the script checks that the oracle's jars are not older than their sources
# (shared-jvm.jar against shared/src/commonMain, engine.jar against engine/src/main).
#
# One deliberate exception: for kind S op `lower`, when the case's input contains U+03A3 (capital sigma), both answers are
# compared after folding U+03C2 to U+03C3 ($Folding below, here and nowhere else): the final sigma form that Kotlin picks
# differs from xgs::kt's approximation of Unicode's Final_Sigma rule in some contexts (qt/README.md). Every other case, op
# and character is compared exactly.
#
# Adding a kind: a generator (gen.cpp, registerGenerators), an answerer (main.cpp, registerAnswers), a `case` in
# Oracle.java, and the kind's thresholds in $Statistics here. A kind without an entry in $Statistics fails.
param(
    [string]$Kinds = 'UXMSCFDGTLYRNBZHOJEQ',
    [int]$PerKind = 10000,
    [long]$Seed = 20261115
)
$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
$image = Join-Path $root 'server/build/sidecar-image'
$java = Join-Path $image 'runtime/bin/java.exe'
$oracle = Join-Path $PSScriptRoot 'Oracle.java'
$tool = Join-Path $root 'build/qt/xgs-diff.exe'
$work = Join-Path $root 'build/qt/differential'

# ---- statistics: one entry per kind ----
# Table kinds: Table = the mode both sides print; Check gets the Kotlin answers. Case kinds: Check gets the cases (each the
# array of fields after the kind letter), the Kotlin answers and the port's answers. A check returns failure messages (none =
# reached).
# The protocol's thresholds are counts for 10000 cases; here they are fractions of the cases, so any -PerKind works.
function Get-Share([int]$count, [int]$total) { if ($total -eq 0) { 0 } else { $count / $total } }
# Shows a measured share (so a passing run says how far above its threshold it is) and returns the failure message when it
# is below $min.
function Test-Share([string]$kind, [string]$label, [int]$count, [int]$total, [double]$min) {
    $share = Get-Share $count $total
    Write-Host ('  {0}: {1}: {2} of {3} = {4:P1} (needs {5:0.##%})' -f $kind, $label, $count, $total, $share, $min)
    if ($share -lt $min) { "${kind}: $label is $count of $total cases (needs $('{0:0.##%}' -f $min))" }
}
# Helpers of the F/D/G statistics, on the hex notation of a field ('-' null, '.' empty, else 4 hex digits per UTF-16 unit).
function Get-UnitCount([string]$field) { if ($field -ceq '-' -or $field -ceq '.') { 0 } else { $field.Length / 4 } }
function Test-SurrogateInRange([string]$field, [int]$from, [int]$to) {
    # a UTF-16 surrogate unit (D800..DFFF) among the units from..to (0-based, inclusive)
    if ($field -ceq '-' -or $field -ceq '.') { return $false }
    for ($i = [Math]::Max(0, $from); $i -le [Math]::Min($to, $field.Length / 4 - 1); $i++) {
        if ($field.Substring($i * 4, 4) -cmatch '^d[89a-f]') { return $true }
    }
    return $false
}
function Test-BlankOnly([string]$field) {
    # not null, not empty, and nothing but white space (the white space strings of nullable() are 1 to 4 units)
    if ($field -ceq '-' -or $field -ceq '.' -or $field.Length -gt 64) { return $false }
    for ($i = 0; $i -lt $field.Length; $i += 4) {
        # Kotlin's Char.isWhitespace(): .NET's IsWhiteSpace plus U+001C..001F (and without U+0085, which Java does not count)
        $unit = [Convert]::ToInt32($field.Substring($i, 4), 16)
        $white = ($unit -ge 0x1C -and $unit -le 0x1F) -or ($unit -ne 0x85 -and [char]::IsWhiteSpace([char]$unit))
        if (-not $white) { return $false }
    }
    return $true
}
function Get-OptionalShares($fields) {
    # null, empty and white-space-only counts of an optional field over all cases
    $null_ = @($fields | Where-Object { $_ -ceq '-' }).Count
    $empty = @($fields | Where-Object { $_ -ceq '.' }).Count
    $blank = @($fields | Where-Object { Test-BlankOnly $_ }).Count
    return @{ null = $null_; empty = $empty; blank = $blank }
}
function Test-OptionalShares([string]$kind, [string]$name, $fields) {
    $total = $fields.Count
    $shares = Get-OptionalShares $fields
    foreach ($which in 'null', 'empty', 'blank') { Test-Share $kind "$name is $which" $shares[$which] $total 0.05 }
}
$UntitledHex = -join ('재생목록'.ToCharArray() | ForEach-Object { '{0:x4}' -f [int]$_ })
$UnknownArtistHex = -join ('Unknown Artist'.ToCharArray() | ForEach-Object { '{0:x4}' -f [int]$_ })
# Helpers of the T statistics. A field decoded for a statistic only (an unpaired surrogate becomes U+FFFD; the comparison of
# the answers is on the hex and is exact).
function ConvertFrom-HexText([string]$field) {
    if ($field -ceq '-') { return $null }
    if ($field -ceq '.') { return '' }
    return [System.Text.Encoding]::BigEndianUnicode.GetString([Convert]::FromHexString($field))
}
# Kotlin's Char.isWhitespace() as a char array for String.Trim(char[]): .NET's IsWhiteSpace plus U+001C..001F, minus U+0085
$KotlinWhitespace = [char[]]@(0..0xFFFF | Where-Object { ($_ -ge 0x1C -and $_ -le 0x1F) -or ($_ -ne 0x85 -and [char]::IsWhiteSpace([char]$_)) } | ForEach-Object { [char]$_ })
$KotlinWhitespaceClass = '[' + (-join ($KotlinWhitespace | ForEach-Object { '\u{0:x4}' -f [int]$_ })) + ']'
$NoiseAlternatives = (@('Official Music Video', 'Official Video', 'Official Audio', 'Official MV', 'Official M/V', 'Performance Video',
                        'Special Video', 'Special Clip', 'Lyric Video', 'Music Video', 'Live Clip', 'Visualizer', 'Audio', 'M/V',
                        'MV') | ForEach-Object { [regex]::Escape($_) }) -join '|'
# a noise token as its own word at the end of the title, bare or in parentheses, perhaps followed by a ` | ...` tail
$TrailingNoisePattern = [regex]::new("(?is)(?:^|$KotlinWhitespaceClass|\()(?:$NoiseAlternatives)(?:$KotlinWhitespaceClass|\))*(?:$KotlinWhitespaceClass\|.*)?$", 'Compiled')
# a `[...]` block at the start, after what stripLeadingJunk drops (white space, surrogates, U+FE0F, U+200D, U+2190..2BFF)
$LeadingTagPattern = [regex]::new("^(?:$KotlinWhitespaceClass|[\uD800-\uDFFF�️‍←-⯿])*\[[^\]]*\]", 'Compiled')
# on the hex of a field, aligned to units: a surrogate pair, and an unpaired surrogate unit
$PairHexPattern = [regex]::new('^(?:[0-9a-f]{4})*?d[89ab][0-9a-f]{2}d[c-f][0-9a-f]{2}', 'Compiled')
$LoneHexPattern = [regex]::new('^(?:[0-9a-f]{4})*?(?:d[89ab][0-9a-f]{2}(?!d[c-f])|(?<!d[89ab][0-9a-f]{2})d[c-f][0-9a-f]{2})', 'Compiled')
$QuoteClass = "['‘’`"“”]"
# Helpers of the L and Y statistics: LyricsExtractor's rules, written again for the statistics only (they are not compared;
# the answers are compared exactly on the hex). Kotlin's white space is $KotlinWhitespace; a letter or digit is .NET's
# \p{L}\p{Nd} (close enough to Java's for counting).
$LyricsMarkers = [System.Collections.Generic.HashSet[string]]::new([string[]]@('lyrics', 'lyric', '가사', '歌詞', '歌词', 'lyrics가사',
    '가사lyrics', 'lyricskorean', 'lyricskor', 'lyricsoriginal'), [StringComparer]::Ordinal)
$ParenthesisedHeadings = [System.Collections.Generic.HashSet[string]]::new([string[]]@('english', 'englishtranslation', 'translation',
    'romanized', 'romanization', '번역', '해석', '영문', '로마자', 'credit', 'credits'), [StringComparer]::Ordinal)
$NotLetterOrDigit = [regex]::new('[^\p{L}\p{Nd}]', 'Compiled')
$SeparatorLine = [regex]::new('^[=\-_*~#.+━─═\u3161\u2014\u25AC\uFF1D]{3,}$', 'Compiled')
$LinkMarker = [regex]::new('https?://|www\.', 'Compiled, IgnoreCase, CultureInvariant')
$CopyrightPrefix = [regex]::new('^(?:©|ⓒ|\(c\)|copyright|all rights reserved)', 'Compiled, IgnoreCase, CultureInvariant')
$HashtagLine = [regex]::new("^#(?!$KotlinWhitespaceClass)[\s\S]", 'Compiled')
$BoilerplateKey = [regex]::new('^(?:provided|releasedon|autogenerated)', 'Compiled')
$OtherSectionKey = [regex]::new('^(?:rom|eng|translat|credit|info|staff|link|sns|follow|번역|해석|영문|로마|크레딧|정보)', 'Compiled')
$ZeroWidth = [regex]::new('[\u200B\u200C\u200D\u2060\uFEFF]', 'Compiled')
$Controls = [regex]::new('[\x00-\x08\x0B-\x1F\x7F-\x9F]', 'Compiled')
$RawLineBreak = [regex]::new('\r\n|\r|\n', 'Compiled')
$InvisibleUnit = [regex]::new('[\u200B\u200C\u200D\u2060\uFEFF\u3164]', 'Compiled')
$TerminatorKinds = 'separator', 'link', 'copyright', 'hashtag', 'boilerplate', 'bracketed heading', 'parenthesised heading'
function ConvertTo-NormalisedLyrics([string]$raw) {
    $visible = $ZeroWidth.Replace($raw, '').Replace([char]0x3164, ' ')
    return $Controls.Replace($visible.Replace("`r`n", "`n").Replace("`r", "`n"), '')
}
function Get-LyricsKey([string]$line) { $NotLetterOrDigit.Replace($line, '').ToLowerInvariant() }
function Test-LyricsHeading([string]$line) {
    $trimmed = $line.Trim($KotlinWhitespace)
    -not $HashtagLine.IsMatch($trimmed) -and $LyricsMarkers.Contains((Get-LyricsKey $line))
}
# 0 for a lyric line, else 1..7: the kind of terminator ($TerminatorKinds), in the order of isTerminator
function Get-TerminatorKind([string]$line) {
    $t = $line.Trim($KotlinWhitespace)
    if ($SeparatorLine.IsMatch($t)) { return 1 }
    if ($LinkMarker.IsMatch($t)) { return 2 }
    if ($CopyrightPrefix.IsMatch($t)) { return 3 }
    if ($HashtagLine.IsMatch($t)) { return 4 }
    $k = Get-LyricsKey $t
    if ($BoilerplateKey.IsMatch($k)) { return 5 }
    if ($t.Length -ge 2 -and (($t[0] -ceq '[' -and $t[-1] -ceq ']') -or ($t[0] -ceq '【' -and $t[-1] -ceq '】'))) {
        if ($LyricsMarkers.Contains($k) -or $OtherSectionKey.IsMatch($k)) { return 6 }
        return 0
    }
    if ($t.Length -ge 2 -and $t[0] -ceq '(' -and $t[-1] -ceq ')' -and $ParenthesisedHeadings.Contains($k)) { return 7 }
    return 0
}
# a surrogate pair at the end of an answer's hex
$EndPairHexPattern = [regex]::new('d[89ab][0-9a-f]{2}d[c-f][0-9a-f]{2}$', 'Compiled')
# the measures shared by L and Y: surrogates, length over 30000 units, answers that end next to the cut
function Test-LyricsCommon([string]$kind, $cases, $answers) {
    $total = $cases.Count
    $pair = 0; $lone = 0; $long = 0; $endPair = 0; $atLimit = 0
    for ($i = 0; $i -lt $total; $i++) {
        $field = $cases[$i][0]
        if ($PairHexPattern.IsMatch($field)) { $pair++ }
        if ($LoneHexPattern.IsMatch($field)) { $lone++ }
        if ((Get-UnitCount $field) -gt 30000) {
            $long++
            $answer = $answers[$i]
            if ($answer -and $answer.StartsWith('OK ')) {
                $units = ($answer.Length - 3) / 4
                if ($EndPairHexPattern.IsMatch($answer)) { $endPair++ }
                if ($units -ge 29997 -and $units -le 30000) { $atLimit++ }
            }
        }
    }
    Test-Share $kind 'input with a surrogate pair' $pair $total 0.05
    Test-Share $kind 'input with an unpaired surrogate' $lone $total 0.02
    Test-Share $kind 'input over 30000 units' $long $total 0.02
    Test-Share $kind 'input over 30000 units, answer ends with a surrogate pair' $endPair $total 0.003
    Test-Share $kind 'input over 30000 units, answer of 29997..30000 units' $atLimit $total 0.003
}
# Helpers of the R and N statistics (patterns on the decoded text, for counting only; the answers are compared exactly).
$PathPlaceholderHex = -join ('<경로>'.ToCharArray() | ForEach-Object { '{0:x4}' -f [int]$_ })
$FileNamePlaceholderHex = -join ('<파일명>'.ToCharArray() | ForEach-Object { '{0:x4}' -f [int]$_ })
# how many times $needle occurs in an answer's hex at a unit boundary
function Get-AlignedCount([string]$answer, [string]$needle) {
    if (-not $answer -or -not $answer.StartsWith('OK ')) { return 0 }
    $hex = $answer.Substring(3)
    $count = 0
    $at = $hex.IndexOf($needle, [StringComparison]::Ordinal)
    while ($at -ge 0) {
        if ($at % 4 -eq 0) { $count++; $at = $hex.IndexOf($needle, $at + $needle.Length, [StringComparison]::Ordinal) }
        else { $at = $hex.IndexOf($needle, $at + 1, [StringComparison]::Ordinal) }
    }
    return $count
}
$PartChar = '[^\\/:*?"<>|\r\n]'
$PathForms = [ordered]@{
    'a plain drive path (C:\part)'          = [regex]::new("(?<![A-Za-z0-9\\/?.:])[A-Za-z]:\\(?![\\/])$PartChar", 'Compiled')
    'doubled separators (C:\\part)'         = [regex]::new("(?<![A-Za-z0-9])[A-Za-z]:(?:[\\/]$PartChar+)*(?:\\\\|//)$PartChar", 'Compiled')
    'a forward-slash drive path (C:/part)'  = [regex]::new("(?<![A-Za-z0-9/\\])[A-Za-z]:/(?![\\/])$PartChar", 'Compiled')
    'a UNC path (\\host\share)'             = [regex]::new("(?<!\\)\\\\[^\\/:*?`"<>|\r\n.]$PartChar*\\$PartChar", 'Compiled')
    'a verbatim drive path (\\?\C:\)'       = [regex]::new('\\\\\?\\[A-Za-z]:\\', 'Compiled')
    'a verbatim UNC path (\\?\UNC\)'        = [regex]::new('\\\\\?\\UNC\\', 'Compiled, IgnoreCase, CultureInvariant')
    'a device drive path (\\.\C:\)'         = [regex]::new('\\\\\.\\[A-Za-z]:\\', 'Compiled')
    'a file URI (file:///)'                 = [regex]::new('file:///', 'Compiled, IgnoreCase, CultureInvariant')
}
$PathStart = '(?:(?<![A-Za-z0-9])[A-Za-z]:[\\/]|\\\\|file:///)'
# anything that may start a path (any `\\`, since `\\?\` and `\\.\` are prefixes): its absence makes a case decoy-only
$AnyPath = [regex]::new("(?<![A-Za-z0-9])[A-Za-z]:[\\/]$PartChar|\\\\|file:///", 'Compiled, IgnoreCase, CultureInvariant')
$TwoPathsListed = [regex]::new("$PathStart$PartChar[^\r\n]*?[,;] $PathStart", 'Compiled, IgnoreCase, CultureInvariant')
$TwoPathsArrow = [regex]::new("$PathStart$PartChar[^\r\n]*? -> $PathStart", 'Compiled, IgnoreCase, CultureInvariant')
$PathThenReason = [regex]::new("(?:(?<![A-Za-z0-9])[A-Za-z]:[\\/]|\\\\)$PartChar(?:$PartChar|[\\/])*: \S", 'Compiled')
$Decoy = [regex]::new('https://|Music\\a\.mp3|\.\.\\x|/usr/lib|[A-Za-z][A-Za-z]:\\', 'Compiled')
# a case with a C++ answer longer than the Kotlin one, or with fewer of a placeholder (0 when nothing differs)
function Test-LeakDirection([string]$kind, $answers, $portAnswers) {
    $leaks = 0
    for ($i = 0; $i -lt $answers.Count; $i++) {
        $k = $answers[$i]; $p = $portAnswers[$i]
        if ($null -eq $k -or $null -eq $p) { continue }
        if ($p.Length -gt $k.Length -or
            (Get-AlignedCount $p $PathPlaceholderHex) -lt (Get-AlignedCount $k $PathPlaceholderHex) -or
            (Get-AlignedCount $p $FileNamePlaceholderHex) -lt (Get-AlignedCount $k $FileNamePlaceholderHex)) { $leaks++ }
    }
    Write-Host "  ${kind}: diagnostic, not a threshold: leak direction (C++ answer longer, or with fewer placeholders, than Kotlin's): $leaks of $($answers.Count)"
    if ($leaks -gt 0) { "${kind}: $leaks answers redact less than Kotlin's" }
}
# Helpers of the H statistics, on the hex of a field (aligned to units): a Hangul jamo (U+1100..11FF, U+3130..318F,
# U+A960..A97F, U+D7B0..D7FF) and a combining mark (U+0300..036F, U+1AB0..1AFF, U+1DC0..1DFF, U+20D0..20FF, U+FE20..FE2F,
# U+3099, U+309A)
$JamoHexPattern = [regex]::new('^(?:[0-9a-f]{4})*?(?:11[0-9a-f]{2}|31[3-8][0-9a-f]|a9[67][0-9a-f]|d7[b-f][0-9a-f])', 'Compiled')
$CombiningHexPattern = [regex]::new('^(?:[0-9a-f]{4})*?(?:03[0-6][0-9a-f]|1a[b-f][0-9a-f]|1d[c-f][0-9a-f]|20[d-f][0-9a-f]|fe2[0-9a-f]|309[9a])', 'Compiled')
# Helpers of the J statistics (on the decoded text, for counting only; the answers are compared exactly).
# a key that occurs again in the same object: the second one after a comma, with balanced brackets in between
$DuplicateKeyPattern = [regex]::new('"((?:[^"\\]|\\.)*)"\s*:(?:"(?:[^"\\]|\\.)*"|[^\[\]{}"]|(?<o>[\[{])|(?<-o>[\]}]))*?(?(o)(?!)),\s*"\1"\s*:', 'Compiled')
# a literal content that standard JSON also has (a number, true or false); any other content of an L is non-standard
$StandardLiteral = [regex]::new('^(?:-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?|true|false)$', 'Compiled')
$LiteralInAnswer = [regex]::new('L((?:[0-9a-f]{4})+)', 'Compiled')
# white space Kotlin does not skip: VT, FF, U+00A0, U+2028, U+3000, U+0085, the BOM, U+001F, NUL
$OtherWhite = [regex]::new('[' + (-join (@(0x0b, 0x0c, 0xa0, 0x2028, 0x3000, 0x85, 0xfeff, 0x1f, 0) | ForEach-Object { '\u{0:x4}' -f $_ })) + ']', 'Compiled')
$EscapedSurrogate = [regex]::new('\\u[dD][89a-fA-F][0-9a-fA-F]{2}', 'Compiled')
$BadEscape = [regex]::new('(?<!\\)(?:\\\\)*\\(?:[^"\\/bfnrtu]|u(?![0-9a-fA-F]{4}))', 'Compiled')
$DeepNesting = [regex]::new('(?:\[|\{"a":|\{"k":1,"a":){1000}', 'Compiled')
# a `]` followed (past white space) by what may start a value (Kotlin takes such a `]` after an array item for a comma)
$BracketBeforeValue = [regex]::new('\][ \t\r\n]*[^,\]}:\x00-\x20]', 'Compiled')
$Statistics = [ordered]@{
    J = @{
        # field: text. ERR 20%; a tree 40%; a tree with a non-standard literal (not a JSON number, true or false) 5%; an
        # input with a repeated key 5%. Categories of the Step 2 observations: an input with white space Kotlin does not
        # skip (or a BOM, U+001F, NUL) 2%, an escaped surrogate 3%, an escape Kotlin rejects 1%, 1000 or more nested
        # containers 0.1%, a `]` before what may start a value 2%, 60000 nested arrays 0.02%
        Check = {
            param($cases, $answers)
            $total = $cases.Count
            $errors = 0; $trees = 0; $odd = 0; $duplicate = 0; $white = 0; $surrogate = 0; $bad = 0; $deep = 0; $bracket = 0; $overflow = 0
            for ($i = 0; $i -lt $total; $i++) {
                $answer = $answers[$i]
                if ($answer -ceq 'ERR') { $errors++ }
                elseif ($answer) {
                    $trees++
                    foreach ($m in $LiteralInAnswer.Matches($answer)) {
                        $content = ConvertFrom-HexText $m.Groups[1].Value
                        if (-not $StandardLiteral.IsMatch($content)) { $odd++; break }
                    }
                }
                $field = $cases[$i][0]
                if ($field.Length -gt 4 * 20000) {
                    $big = ConvertFrom-HexText $field
                    if ($DeepNesting.IsMatch($big)) { $deep++ }
                    if ($big.StartsWith('[' * 60000, [StringComparison]::Ordinal)) { $overflow++ }
                    continue
                }
                $raw = ConvertFrom-HexText $field
                if ($null -eq $raw) { $raw = '' }
                if ($DuplicateKeyPattern.IsMatch($raw)) { $duplicate++ }
                if ($OtherWhite.IsMatch($raw)) { $white++ }
                if ($EscapedSurrogate.IsMatch($raw)) { $surrogate++ }
                if ($BadEscape.IsMatch($raw)) { $bad++ }
                if ($BracketBeforeValue.IsMatch($raw)) { $bracket++ }
                if ($raw.Length -ge 1000 -and $DeepNesting.IsMatch($raw)) { $deep++ }
            }
            Test-Share 'J' 'answer ERR' $errors $total 0.20
            Test-Share 'J' 'answer a tree' $trees $total 0.40
            Test-Share 'J' 'answer a tree with a non-standard literal' $odd $total 0.05
            Test-Share 'J' 'input with a repeated key' $duplicate $total 0.05
            Test-Share 'J' 'input with white space Kotlin does not skip, a BOM, U+001F or NUL' $white $total 0.02
            Test-Share 'J' 'input with an escaped surrogate' $surrogate $total 0.03
            Test-Share 'J' 'input with an escape Kotlin rejects' $bad $total 0.01
            Test-Share 'J' 'input nesting 1000 or more containers' $deep $total 0.001
            Test-Share 'J' 'input with a ] before what may start a value' $bracket $total 0.02
            Test-Share 'J' 'input nesting 60000 arrays (Kotlin: always a stack overflow)' $overflow $total 0.0002
        }
    }
    U = @{
        Table = 'unicodecase'
        Check = { param($answers) if ($answers.Count -ne 1112064) { "U: $($answers.Count) code points, not 1112064" } }
    }
    X = @{
        Table = 'chartable'
        Check = { param($answers) if ($answers.Count -ne 65536) { "X: $($answers.Count) units, not 65536" } }
    }
    M = @{
        Table = 'constants'
        Check = { param($answers) if ($answers.Count -ne 11) { "M: $($answers.Count) constants, not 11" } }
    }
    B = @{
        Table = 'lettertable'
        Check = { param($answers) if ($answers.Count -ne 1112064) { "B: $($answers.Count) code points, not 1112064" } }
    }
    Z = @{
        Table = 'nfkctable'
        Check = { param($answers) if ($answers.Count -ne 1112064) { "Z: $($answers.Count) code points, not 1112064" } }
    }
    H = @{
        # field: text. An answer that differs from the input 40%; an input with a Hangul jamo (conjoining or compatibility)
        # 10%; an input with a combining mark 10%
        Check = {
            param($cases, $answers)
            $total = $cases.Count
            $changed = 0; $jamo = 0; $combining = 0
            for ($i = 0; $i -lt $total; $i++) {
                $field = $cases[$i][0]
                if ($answers[$i] -cne "OK $field") { $changed++ }
                if ($JamoHexPattern.IsMatch($field)) { $jamo++ }
                if ($CombiningHexPattern.IsMatch($field)) { $combining++ }
            }
            Test-Share 'H' 'answer differs from the input' $changed $total 0.40
            Test-Share 'H' 'input with a Hangul jamo' $jamo $total 0.10
            Test-Share 'H' 'input with a combining mark' $combining $total 0.10
        }
    }
    O = @{
        # field: text. NULL 30%; a value 30%; an infinity or NaN 2%
        Check = {
            param($cases, $answers)
            $total = $cases.Count
            $nulls = @($answers | Where-Object { $_ -ceq 'NULL' }).Count
            $special = @($answers | Where-Object { $_ -cmatch '^[7f]ff' }).Count
            Test-Share 'O' 'answer NULL' $nulls $total 0.30
            Test-Share 'O' 'answer a value' ($total - $nulls) $total 0.30
            Test-Share 'O' 'answer an infinity or NaN' $special $total 0.02
        }
    }
    E = @{
        # fields: line1 [line2 ...] (no field, or one empty field, for no lines). Answers FATAL, UNAVAILABLE, TRANSIENT and
        # OTHER each 10%
        Check = {
            param($cases, $answers)
            $total = $cases.Count
            foreach ($kind in 'FATAL', 'UNAVAILABLE', 'TRANSIENT', 'OTHER') {
                $count = @($answers | Where-Object { $_.StartsWith("$kind ") }).Count
                Test-Share 'E' "answer $kind" $count $total 0.10
            }
        }
    }
    Q = @{
        # field: line. NULL 15%; `P -` (a percent of null) 15%; a value 15%, of which the value 0 2% and the value 100 2%
        Check = {
            param($cases, $answers)
            $total = $cases.Count
            $nulls = @($answers | Where-Object { $_ -ceq 'NULL' }).Count
            $unknown = @($answers | Where-Object { $_ -ceq 'P -' }).Count
            $values = @($answers | Where-Object { $_.StartsWith('P ') -and $_ -cne 'P -' }).Count
            $zero = @($answers | Where-Object { $_ -ceq 'P 0000000000000000' }).Count
            $hundred = @($answers | Where-Object { $_ -ceq 'P 4059000000000000' }).Count
            Test-Share 'Q' 'answer NULL' $nulls $total 0.15
            Test-Share 'Q' 'answer P - (no percent)' $unknown $total 0.15
            Test-Share 'Q' 'answer a value' $values $total 0.15
            Test-Share 'Q' 'answer the value 0' $zero $total 0.02
            Test-Share 'Q' 'answer the value 100' $hundred $total 0.02
        }
    }
    S = @{
        Check = {
            param($cases, $answers)
            # every op takes a share of the cases (15 ops: about 6.7% each, needs 5%); the boolean ops need both answers 15%,
            # blank both answers 5%, ci-index 20% that are not -1
            $ops = 'lower', 'upper', 'trim', 'trimStart', 'trimEnd', 'blank', 'ci-starts', 'ci-ends', 'ci-contains', 'ci-index',
                   'ci-replace', 'eqic', 'index', 'replace', 'ci-starts-from'
            $booleans = 'ci-starts', 'ci-ends', 'ci-contains', 'eqic', 'ci-starts-from'
            $byOp = @{}
            foreach ($op in $ops) { $byOp[$op] = [System.Collections.Generic.List[int]]::new() }
            for ($c = 0; $c -lt $cases.Count; $c++) { $list = $byOp[$cases[$c][0]]; if ($null -ne $list) { $list.Add($c) } }
            foreach ($op in $ops) {
                $indexes = $byOp[$op]
                $count = $indexes.Count
                Test-Share 'S' "op $op" $count $cases.Count 0.05
                $minimum = if ($booleans -contains $op) { 0.15 } elseif ($op -ceq 'blank') { 0.05 } else { -1 }
                if ($minimum -gt 0) {
                    foreach ($answer in '0', '1') {
                        $n = @($indexes | Where-Object { $answers[$_] -ceq $answer }).Count
                        Test-Share 'S' "op $op answers $answer" $n $count $minimum
                    }
                }
                if ($op -ceq 'ci-index') {
                    $found = @($indexes | Where-Object { $answers[$_] -cne '-1' }).Count
                    Test-Share 'S' 'op ci-index finds' $found $count 0.2
                }
            }
        }
    }
    F = @{
        # fields: rank includeRank artist title. ERR 1%, an ellipsis (2026) in 5% of the answers; the 80 and 180 limits: an
        # artist of 77..83 units, a title within 3 units of what the prefix leaves (180 - rank prefix - artist - " - "), each
        # with a surrogate unit at the cut, in at least 5% of the cases
        Check = {
            param($cases, $answers)
            $total = $cases.Count
            $errors = @($answers | Where-Object { $_ -ceq 'ERR' }).Count
            Test-Share 'F' 'answer ERR' $errors $total 0.01
            $ellipsis = @($answers | Where-Object { $_ -cmatch '^OK (?:[0-9a-f]{4})*?2026' }).Count
            Test-Share 'F' 'answer with an ellipsis' $ellipsis $total 0.05
            $artistNear = 0; $artistCut = 0; $titleNear = 0; $titleCut = 0
            foreach ($case in $cases) {
                $artistUnits = Get-UnitCount $case[2]
                if ($artistUnits -ge 77 -and $artistUnits -le 83) {
                    $artistNear++
                    if (Test-SurrogateInRange $case[2] 76 79) { $artistCut++ }
                }
                $limit = 180 - $(if ($case[1] -ceq '1') { 4 } else { 0 }) - [Math]::Min($artistUnits, 80) - 3
                $titleUnits = Get-UnitCount $case[3]
                if ([Math]::Abs($titleUnits - $limit) -le 3) {
                    $titleNear++
                    if (Test-SurrogateInRange $case[3] ($limit - 4) ($limit - 1)) { $titleCut++ }
                }
            }
            Test-Share 'F' 'artist of 77..83 units' $artistNear $total 0.05
            Test-Share 'F' 'surrogate at the artist cut' $artistCut $total 0.05
            Test-Share 'F' 'title within 3 units of its limit' $titleNear $total 0.05
            Test-Share 'F' 'surrogate at the title cut' $titleCut $total 0.05
        }
    }
    D = @{
        # field: title. Untitled answers 5%, a device-name `_` 2%, null / empty / white space only 5% each, a title of 77..83
        # units with a surrogate at the cut 5% each
        Check = {
            param($cases, $answers)
            $total = $cases.Count
            $untitled = @($answers | Where-Object { $_ -ceq "OK $UntitledHex" }).Count
            Test-Share 'D' 'answer is the untitled folder' $untitled $total 0.05
            $device = 0
            foreach ($answer in $answers) {
                if (-not $answer.StartsWith('OK ') -or $answer -ceq "OK $UntitledHex") { continue }
                $head = $answer.Substring(3, [Math]::Min($answer.Length - 3, 40))
                $decoded = ''
                for ($i = 0; $i + 4 -le $head.Length; $i += 4) { $decoded += [char][Convert]::ToInt32($head.Substring($i, 4), 16) }
                if ($decoded -match '^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])_') { $device++ }
            }
            Test-Share 'D' 'answer with a device name and _' $device $total 0.02
            $titles = @($cases | ForEach-Object { $_[0] })
            Test-OptionalShares 'D' 'the title' $titles
            $near = @($titles | Where-Object { $u = Get-UnitCount $_; $u -ge 77 -and $u -le 83 }).Count
            $cut = @($titles | Where-Object { Test-SurrogateInRange $_ 76 79 }).Count
            Test-Share 'D' 'title of 77..83 units' $near $total 0.05
            Test-Share 'D' 'surrogate at the cut' $cut $total 0.05
        }
    }
    G = @{
        # fields: isPlaylist playlistTitle typed. NULL 5%; each optional field null / empty / white space only 5% each
        Check = {
            param($cases, $answers)
            $total = $cases.Count
            $nulls = @($answers | Where-Object { $_ -ceq 'NULL' }).Count
            Test-Share 'G' 'answer NULL' $nulls $total 0.05
            Test-OptionalShares 'G' 'playlistTitle' @($cases | ForEach-Object { $_[1] })
            Test-OptionalShares 'G' 'typed' @($cases | ForEach-Object { $_[2] })
        }
    }
    T = @{
        # fields: rawTitle channel metaArtist metaTrack. Each confidence 10%; channel, metaArtist and metaTrack null / empty /
        # white space only 5% each; a title taken from a quoted span 5%; a Topic channel 5%; a raw title with a trailing noise
        # token 10% and with a leading [...] tag 10%; the port's artist `Unknown Artist` 2%; a raw title with a surrogate pair
        # 5% and with an unpaired surrogate 2%
        Check = {
            param($cases, $answers, $portAnswers)
            $total = $cases.Count
            foreach ($confidence in 'HIGH', 'MEDIUM', 'LOW') {
                $n = @($answers | Where-Object { $_ -and $_.EndsWith(" $confidence") }).Count
                Test-Share 'T' "confidence $confidence" $n $total 0.10
            }
            Test-OptionalShares 'T' 'channel' @($cases | ForEach-Object { $_[1] })
            Test-OptionalShares 'T' 'metaArtist' @($cases | ForEach-Object { $_[2] })
            Test-OptionalShares 'T' 'metaTrack' @($cases | ForEach-Object { $_[3] })
            $quoted = 0; $topic = 0; $noise = 0; $tag = 0; $unknown = 0; $pair = 0; $lone = 0
            for ($i = 0; $i -lt $total; $i++) {
                $case = $cases[$i]
                $raw = ConvertFrom-HexText $case[0]
                if ($null -eq $raw) { $raw = '' }
                $collapsed = [regex]::Replace($raw, "$KotlinWhitespaceClass+", ' ')
                $answer = $answers[$i]
                if ($answer -and $answer.StartsWith('OK ')) {
                    $title = ConvertFrom-HexText ($answer.Split(' ')[2])
                    if ($title -and [regex]::IsMatch($collapsed, $QuoteClass + ' ?' + [regex]::Escape($title) + ' ?' + $QuoteClass)) { $quoted++ }
                }
                $channel = ConvertFrom-HexText $case[1]
                if ($null -ne $channel -and $channel.Trim($KotlinWhitespace).EndsWith(' - Topic', [StringComparison]::OrdinalIgnoreCase)) { $topic++ }
                if ($TrailingNoisePattern.IsMatch($raw)) { $noise++ }
                if ($LeadingTagPattern.IsMatch($raw)) { $tag++ }
                $port = $portAnswers[$i]
                if ($port -and $port.StartsWith('OK ') -and $port.Split(' ')[1] -ceq $UnknownArtistHex) { $unknown++ }
                if ($PairHexPattern.IsMatch($case[0])) { $pair++ }
                if ($LoneHexPattern.IsMatch($case[0])) { $lone++ }
            }
            Test-Share 'T' 'title taken from a quoted span' $quoted $total 0.05
            Test-Share 'T' 'Topic channel' $topic $total 0.05
            Test-Share 'T' 'raw title with a trailing noise token' $noise $total 0.10
            Test-Share 'T' 'raw title with a leading [...] tag' $tag $total 0.10
            Test-Share 'T' 'port answer artist is Unknown Artist' $unknown $total 0.02
            Test-Share 'T' 'raw title with a surrogate pair' $pair $total 0.05
            Test-Share 'T' 'raw title with an unpaired surrogate' $lone $total 0.02
        }
    }
    L = @{
        # field: description. OK 20%, NULL 20%; null / empty / white space only 5% each; a real heading line 40%; a fake
        # heading (a hashtag line or more than a heading, before the real one) 5%; a zero-width character or U+3164 in the
        # heading line 5%; each line break style (`\n`, `\r\n`, a lone `\r`) 10%; the block ended by a terminator of each of
        # the seven kinds 3% each; an OK answer whose block a terminator ended (not the end of the text) 10%; and the
        # measures of Test-LyricsCommon
        Check = {
            param($cases, $answers)
            $total = $cases.Count
            Test-Share 'L' 'answer OK' @($answers | Where-Object { $_ -and $_.StartsWith('OK ') }).Count $total 0.20
            Test-Share 'L' 'answer NULL' @($answers | Where-Object { $_ -ceq 'NULL' }).Count $total 0.20
            Test-OptionalShares 'L' 'the description' @($cases | ForEach-Object { $_[0] })
            $real = 0; $fake = 0; $invisible = 0; $lf = 0; $crlf = 0; $cr = 0; $cut = 0
            $terminators = [int[]]::new(8)
            for ($i = 0; $i -lt $total; $i++) {
                $raw = ConvertFrom-HexText $cases[$i][0]
                if ([string]::IsNullOrEmpty($raw)) { continue }
                if ($raw.Contains("`r`n")) { $crlf++ }
                if ([regex]::IsMatch($raw, '(?<!\r)\n')) { $lf++ }
                if ([regex]::IsMatch($raw, '\r(?!\n)')) { $cr++ }
                foreach ($rawLine in $RawLineBreak.Split($raw)) {
                    if (Test-LyricsHeading (ConvertTo-NormalisedLyrics $rawLine)) {
                        if ($InvisibleUnit.IsMatch($rawLine)) { $invisible++ }
                        break
                    }
                }
                $lines = (ConvertTo-NormalisedLyrics $raw).Split("`n")
                $heading = -1
                $sawFake = $false
                for ($l = 0; $l -lt $lines.Count; $l++) {
                    if (Test-LyricsHeading $lines[$l]) { $heading = $l; break }
                    $trimmed = $lines[$l].Trim($KotlinWhitespace)
                    $key = Get-LyricsKey $lines[$l]
                    if (($HashtagLine.IsMatch($trimmed) -and $LyricsMarkers.Contains($key)) -or $key.StartsWith('lyric') -or $key.StartsWith('가사')) { $sawFake = $true }
                }
                if ($sawFake) { $fake++ }
                if ($heading -lt 0) { continue }
                $real++
                $start = $heading + 1
                while ($start -lt $lines.Count -and ($lines[$start].Trim($KotlinWhitespace).Length -eq 0 -or $SeparatorLine.IsMatch($lines[$start].Trim($KotlinWhitespace)))) { $start++ }
                for ($end = $start; $end -lt $lines.Count; $end++) {
                    $kind = Get-TerminatorKind $lines[$end]
                    if ($kind -gt 0) {
                        $terminators[$kind]++
                        if ($answers[$i] -and $answers[$i].StartsWith('OK ')) { $cut++ }
                        break
                    }
                }
            }
            Test-Share 'L' 'description with a real heading line' $real $total 0.40
            Test-Share 'L' 'description with a fake heading' $fake $total 0.05
            Test-Share 'L' 'heading line with a zero-width character or U+3164' $invisible $total 0.05
            Test-Share 'L' 'description with a \n line break' $lf $total 0.10
            Test-Share 'L' 'description with a \r\n line break' $crlf $total 0.10
            Test-Share 'L' 'description with a lone \r line break' $cr $total 0.10
            for ($k = 1; $k -le 7; $k++) { Test-Share 'L' "block ended by a $($TerminatorKinds[$k - 1]) line" $terminators[$k] $total 0.03 }
            Test-Share 'L' 'answer OK and its block ended by a terminator' $cut $total 0.10
            Test-LyricsCommon 'L' $cases $answers
        }
    }
    Y = @{
        # field: text. OK 20%, NULL 10%; null / empty / white space only 5% each; a run of three or more blank lines 10%; and
        # the measures of Test-LyricsCommon
        Check = {
            param($cases, $answers)
            $total = $cases.Count
            Test-Share 'Y' 'answer OK' @($answers | Where-Object { $_ -and $_.StartsWith('OK ') }).Count $total 0.20
            Test-Share 'Y' 'answer NULL' @($answers | Where-Object { $_ -ceq 'NULL' }).Count $total 0.10
            Test-OptionalShares 'Y' 'the text' @($cases | ForEach-Object { $_[0] })
            $runs = 0
            foreach ($case in $cases) {
                $raw = ConvertFrom-HexText $case[0]
                if ([string]::IsNullOrEmpty($raw)) { continue }
                $blankRun = 0
                foreach ($line in (ConvertTo-NormalisedLyrics $raw).Split("`n")) {
                    if ($line.Trim($KotlinWhitespace).Length -eq 0) { $blankRun++ } else { $blankRun = 0 }
                    if ($blankRun -ge 3) { $runs++; break }
                }
            }
            Test-Share 'Y' 'text with a run of 3 or more blank lines' $runs $total 0.10
            Test-LyricsCommon 'Y' $cases $answers
        }
    }
    R = @{
        # field: text. Answers with <경로> 30% and without 20%; each path form 3%; two paths joined by `, ` or `; ` 5%, by
        # ` -> ` 5%; a `: reason` after a path 5%; a decoy 10%, and among the decoy-only cases (a decoy and nothing that
        # starts a path) Kotlin's answer without <경로> in 90%; input over 4000 units 3%, with a surrogate unit at unit 3999
        # 1%, with a path running over unit 4000 1%; a surrogate pair 5% and an unpaired surrogate 2%; and the leak direction
        Check = {
            param($cases, $answers, $portAnswers)
            $total = $cases.Count
            $with = @($answers | Where-Object { (Get-AlignedCount $_ $PathPlaceholderHex) -gt 0 }).Count
            Test-Share 'R' 'answer with <경로>' $with $total 0.30
            Test-Share 'R' 'answer without <경로>' ($total - $with) $total 0.20
            $forms = @{}; foreach ($name in $PathForms.Keys) { $forms[$name] = 0 }
            $listed = 0; $arrow = 0; $reason = 0; $decoys = 0; $decoyOnly = 0; $decoyOnlyClean = 0
            $long = 0; $longSurrogate = 0; $longPath = 0; $pair = 0; $lone = 0
            for ($i = 0; $i -lt $total; $i++) {
                $field = $cases[$i][0]
                $raw = ConvertFrom-HexText $field
                if ($null -eq $raw) { $raw = '' }
                foreach ($name in $PathForms.Keys) { if ($PathForms[$name].IsMatch($raw)) { $forms[$name]++ } }
                if ($TwoPathsListed.IsMatch($raw)) { $listed++ }
                if ($TwoPathsArrow.IsMatch($raw)) { $arrow++ }
                if ($PathThenReason.IsMatch($raw)) { $reason++ }
                if ($Decoy.IsMatch($raw)) {
                    $decoys++
                    if (-not $AnyPath.IsMatch($raw)) {
                        $decoyOnly++
                        if ((Get-AlignedCount $answers[$i] $PathPlaceholderHex) -eq 0) { $decoyOnlyClean++ }
                    }
                }
                if ((Get-UnitCount $field) -gt 4000) {
                    $long++
                    if (Test-SurrogateInRange $field 3999 3999) { $longSurrogate++ }
                    # a path that starts within the 200 units before the cut and has no line break or forbidden character
                    # up to unit 4000
                    $window = $raw.Substring(3800, 201)
                    if ([regex]::IsMatch($window, "$PathStart(?:$PartChar|[\\/])*$")) { $longPath++ }
                }
                if ($PairHexPattern.IsMatch($field)) { $pair++ }
                if ($LoneHexPattern.IsMatch($field)) { $lone++ }
            }
            foreach ($name in $PathForms.Keys) { Test-Share 'R' "input with $name" $forms[$name] $total 0.03 }
            Test-Share 'R' 'input with two paths joined by , or ;' $listed $total 0.05
            Test-Share 'R' 'input with two paths joined by ->' $arrow $total 0.05
            Test-Share 'R' 'input with a : reason after a path' $reason $total 0.05
            Test-Share 'R' 'input with a decoy' $decoys $total 0.10
            Test-Share 'R' 'decoy-only input whose Kotlin answer has no <경로>' $decoyOnlyClean $decoyOnly 0.90
            Test-Share 'R' 'input over 4000 units' $long $total 0.03
            Test-Share 'R' 'input over 4000 units with a surrogate unit at unit 3999' $longSurrogate $total 0.01
            Test-Share 'R' 'input over 4000 units with a path running over the cut' $longPath $total 0.01
            Test-Share 'R' 'input with a surrogate pair' $pair $total 0.05
            Test-Share 'R' 'input with an unpaired surrogate' $lone $total 0.02
            Test-LeakDirection 'R' $answers $portAnswers
        }
    }
    N = @{
        # fields: text name1 [name2 ...]. Answers with <파일명> 20%; a name found in another case than given 5%; a name
        # shorter than 3 units or blank 5%; a name inside a path 5%; one name a prefix of another 3%; and the leak direction
        Check = {
            param($cases, $answers, $portAnswers)
            $total = $cases.Count
            $with = @($answers | Where-Object { (Get-AlignedCount $_ $FileNamePlaceholderHex) -gt 0 }).Count
            Test-Share 'N' 'answer with <파일명>' $with $total 0.20
            $otherCase = 0; $short = 0; $inPath = 0; $prefix = 0
            for ($i = 0; $i -lt $total; $i++) {
                $raw = ConvertFrom-HexText $cases[$i][0]
                if ($null -eq $raw) { $raw = '' }
                $names = @($cases[$i][1..($cases[$i].Count - 1)] | ForEach-Object { $n = ConvertFrom-HexText $_; if ($null -eq $n) { '' } else { $n } })
                $sawOther = $false; $sawShort = $false; $sawInPath = $false; $sawPrefix = $false
                foreach ($name in $names) {
                    $stem = $(if ($name.LastIndexOf('.') -ge 0) { $name.Substring(0, $name.LastIndexOf('.')) } else { $name })
                    if ($name.Length -lt 3 -or $name.Trim($KotlinWhitespace).Length -eq 0) { $sawShort = $true; continue }
                    foreach ($form in @($name, $stem)) {
                        if ($form.Length -lt 3 -or $form.Trim($KotlinWhitespace).Length -eq 0) { continue }
                        $escaped = [regex]::Escape($form)
                        $ci = [regex]::Matches($raw, $escaped, 'IgnoreCase, CultureInvariant').Count
                        $cs = [regex]::Matches($raw, $escaped).Count
                        if ($ci -gt $cs) { $sawOther = $true }
                        if ([regex]::IsMatch($raw, "[\\/]$escaped", 'IgnoreCase, CultureInvariant')) { $sawInPath = $true }
                    }
                    foreach ($other in $names) {
                        if ($other.Length -gt $name.Length -and $other.StartsWith($name, [StringComparison]::Ordinal)) { $sawPrefix = $true }
                    }
                }
                if ($sawOther) { $otherCase++ }
                if ($sawShort) { $short++ }
                if ($sawInPath) { $inPath++ }
                if ($sawPrefix) { $prefix++ }
            }
            Test-Share 'N' 'a name found in another case than given' $otherCase $total 0.05
            Test-Share 'N' 'a name shorter than 3 units or blank' $short $total 0.05
            Test-Share 'N' 'a name inside a path' $inPath $total 0.05
            Test-Share 'N' 'one name a prefix of another' $prefix $total 0.03
            Test-LeakDirection 'N' $answers $portAnswers
        }
    }
    C = @{
        Check = {
            param($cases, $answers)
            $total = $answers.Count
            $groups = [ordered]@{
                'P' = 'P '; 'V' = 'V '; 'REJECT EMPTY' = 'REJECT EMPTY'; 'REJECT UNSUPPORTED_HOST' = 'REJECT UNSUPPORTED_HOST'
                'REJECT MIX_PLAYLIST' = 'REJECT MIX_PLAYLIST'; 'REJECT UNRECOGNIZED' = 'REJECT UNRECOGNIZED'
            }
            foreach ($name in $groups.Keys) {
                $prefix = $groups[$name]
                $count = @($answers | Where-Object { $_ -and $_.StartsWith($prefix) }).Count
                Test-Share 'C' "answer $name" $count $total 0.05
            }
        }
    }
}

# ---- comparison folding: kind -> script block (case fields, answer) -> the answer to compare ----
# true when a field's hex holds U+03A3 at a unit boundary
function Test-HasCapitalSigma([string]$field) {
    if ($field -ceq '-' -or $field -ceq '.') { return $false }
    for ($i = 0; $i + 4 -le $field.Length; $i += 4) { if ($field.Substring($i, 4) -ceq '03a3') { return $true } }
    return $false
}
function Format-FoldedSigma([string]$answer) {
    if ($null -eq $answer -or -not $answer.StartsWith('OK ')) { return $answer }
    $hex = $answer.Substring(3)
    $sb = [System.Text.StringBuilder]::new($answer.Length)
    [void]$sb.Append('OK ')
    for ($i = 0; $i + 4 -le $hex.Length; $i += 4) {
        $unit = $hex.Substring($i, 4)
        [void]$sb.Append($(if ($unit -ceq '03c2') { '03c3' } else { $unit }))
    }
    if ($hex.Length % 4 -ne 0) { [void]$sb.Append($hex.Substring($hex.Length - ($hex.Length % 4))) }
    return $sb.ToString()
}
$Folding = @{
    S = @{
        Note = 'S: op lower on an input with U+03A3 is compared modulo the final-sigma form (U+03C2 folded to U+03C3 in both answers); all else exactly'
        Fold = { param($fields, $answer) if ($fields[0] -ceq 'lower' -and (Test-HasCapitalSigma $fields[1])) { Format-FoldedSigma $answer } else { $answer } }
    }
}

if ($PerKind -le 0) { throw "-PerKind must be positive, not $PerKind" }
if (-not (Test-Path $java)) {
    Write-Output "no sidecar image at $image; building it first: .\gradlew.bat --no-daemon :server:sidecarImage"
    Push-Location $root
    try { & .\gradlew.bat --no-daemon :server:sidecarImage; if ($LASTEXITCODE -ne 0) { throw "the sidecar image build failed" } }
    finally { Pop-Location }
}
# A stale oracle would compare the port with an old Kotlin: each jar must not be older than the newest file of its sources.
$OracleJars = [ordered]@{
    'lib/shared-jvm.jar' = 'shared/src/commonMain'
    'lib/engine.jar'     = 'engine/src/main'
}
foreach ($jarPath in $OracleJars.Keys) {
    $jar = Join-Path $image $jarPath
    $sources = Join-Path $root $OracleJars[$jarPath]
    if (-not (Test-Path $jar)) { Write-Output "FAILED: no $jar (rebuild the sidecar image: .\gradlew.bat --no-daemon :server:sidecarImage)"; exit 1 }
    if (-not (Test-Path $sources)) { Write-Output "FAILED: no $sources (the sources of $jarPath moved; update `$OracleJars)"; exit 1 }
    $newestSource = Get-ChildItem -LiteralPath $sources -Recurse -File | Sort-Object LastWriteTimeUtc -Descending | Select-Object -First 1
    $jarTime = (Get-Item -LiteralPath $jar).LastWriteTimeUtc
    if ($newestSource -and $newestSource.LastWriteTimeUtc -gt $jarTime) {
        Write-Output ("FAILED: the oracle's {0} ({1:u}) is older than {2} ({3:u}); rebuild the sidecar image first: .\gradlew.bat --no-daemon :server:sidecarImage" -f
                      $jar.Substring($root.Length + 1), $jarTime, $newestSource.FullName.Substring($root.Length + 1), $newestSource.LastWriteTimeUtc)
        exit 1
    }
}
if (-not (Test-Path $tool)) { throw "no $tool; build first (see qt/README.md)" }
New-Item -ItemType Directory -Force $work | Out-Null

# Runs a program with stdin from a file (or none) and returns its stdout lines; a non-zero exit code is an error.
function Invoke-Side([string]$exe, [string[]]$arguments, [string]$inputFile, [string]$name) {
    $outFile = Join-Path $work "$name.out"
    $errFile = Join-Path $work "$name.err"
    $quoted = $arguments | ForEach-Object { '"' + $_ + '"' }
    $options = @{ FilePath = $exe; ArgumentList = $quoted; RedirectStandardOutput = $outFile; RedirectStandardError = $errFile
                  NoNewWindow = $true; Wait = $true; PassThru = $true }
    if ($inputFile) { $options.RedirectStandardInput = $inputFile }
    $process = Start-Process @options
    if ($process.ExitCode -ne 0) { throw "$name failed ($($process.ExitCode)): $(Get-Content -Raw $errFile)" }
    $lines = [System.IO.File]::ReadAllLines($outFile, [System.Text.Encoding]::ASCII)
    Remove-Item -LiteralPath $outFile
    return , $lines
}
$oracleArgs = @('-cp', (Join-Path $image 'lib/*'), $oracle)

function ConvertFrom-Field([string]$field) {
    if ($field -eq '-') { return '(null)' }
    if ($field -eq '.') { return '(empty)' }
    if ($field -cnotmatch '^([0-9a-f]{4})+$') { return $field }
    $sb = [System.Text.StringBuilder]::new('"')
    for ($i = 0; $i -lt $field.Length; $i += 4) {
        $unit = [Convert]::ToInt32($field.Substring($i, 4), 16)
        if ($unit -ge 0x20 -and $unit -lt 0x7F -and $unit -ne 0x22 -and $unit -ne 0x5C) { [void]$sb.Append([char]$unit) }
        else { [void]$sb.Append(('\u{0:X4}' -f $unit)) }
    }
    return $sb.Append('"').ToString()
}
function ConvertFrom-Answer([string]$answer) {
    if ($null -eq $answer) { return '(no answer)' }
    return (($answer -split ' ') | ForEach-Object { ConvertFrom-Field $_ }) -join ' '
}

$failures = [System.Collections.Generic.List[string]]::new()
$summary = [System.Collections.Generic.List[string]]::new()
$script:shown = 0
$letters = @($Kinds.ToCharArray() | ForEach-Object { "$_" } | Select-Object -Unique)
if ($letters.Count -eq 0) { throw 'no kinds given' }
foreach ($letter in $letters) { if (-not $Statistics.Contains($letter)) { $failures.Add("${letter}: no statistics defined for this kind") } }

# ---- table kinds ----
function Invoke-TableKind([string]$letter) {
    $mode = $Statistics[$letter].Table
    $kotlin = Invoke-Side $java ($oracleArgs + $mode) $null "kotlin-$mode"
    $port = Invoke-Side $tool @($mode) $null "port-$mode"
    $mismatches = 0
    if ($kotlin.Count -ne $port.Count) { $failures.Add("${letter}: Kotlin wrote $($kotlin.Count) lines, the port $($port.Count)") }
    # the common case first: identical tables (one fast comparison instead of a loop over a million lines)
    if ($kotlin.Count -ne $port.Count -or -not [System.Linq.Enumerable]::SequenceEqual([string[]]$kotlin, [string[]]$port, [StringComparer]::Ordinal)) {
        for ($i = 0; $i -lt [Math]::Max($kotlin.Count, $port.Count); $i++) {
            $k = if ($i -lt $kotlin.Count) { $kotlin[$i] } else { $null }
            $p = if ($i -lt $port.Count) { $port[$i] } else { $null }
            if ($k -cne $p) {
                $mismatches++
                if ($script:shown -lt 12) {
                    $script:shown++
                    Write-Output ('MISMATCH [{0}] line {1} (U+{1:X4} for X; a U, B or Z line starts with its code point)' -f $letter, $i)
                    Write-Output "   kotlin: $k"
                    Write-Output "   port:   $p"
                }
            }
        }
    }
    if ($mismatches -gt 0) { $failures.Add("${letter}: $mismatches mismatches") }
    foreach ($message in @(& $Statistics[$letter].Check $kotlin)) { if ($message) { $failures.Add($message) } }
    $unit = if ($letter -eq 'X') { 'units' } elseif ($letter -eq 'M') { 'constants' } elseif ('U', 'B', 'Z' -ccontains $letter) { 'code points' } else { 'lines' }
    $summary.Add("${letter}: $($kotlin.Count) $unit, $mismatches mismatches")
}

# ---- case kinds: one kind at a time ----
function Invoke-CaseKind([string]$letter) {
    $generated = Invoke-Side $tool @('gen', $letter, "$PerKind", "$Seed") $null "gen-$letter"
    if ($generated.Count -ne $PerKind) { $failures.Add("${letter}: xgs-diff generated $($generated.Count) cases, not $PerKind") }
    $caseFile = Join-Path $work "cases-$letter.txt"
    [System.IO.File]::WriteAllText($caseFile, (($generated -join "`n") + "`n"), [System.Text.Encoding]::ASCII)
    $kotlin = Invoke-Side $java $oracleArgs $caseFile "kotlin-answers-$letter"
    $port = Invoke-Side $tool @('answer') $caseFile "port-answers-$letter"
    Remove-Item -LiteralPath $caseFile
    if ($kotlin.Count -ne $generated.Count) { $failures.Add("${letter}: Kotlin answered $($kotlin.Count) of $($generated.Count) cases") }
    if ($port.Count -ne $generated.Count) { $failures.Add("${letter}: the port answered $($port.Count) of $($generated.Count) cases") }
    $cases = [System.Collections.Generic.List[object]]::new($generated.Count)
    $answers = [System.Collections.Generic.List[string]]::new($generated.Count)
    $portAnswers = [System.Collections.Generic.List[string]]::new($generated.Count)
    $mismatches = 0; $unknown = 0
    $folding = $Folding[$letter]
    for ($i = 0; $i -lt $generated.Count; $i++) {
        $fields = $generated[$i].Split("`t")
        $generated[$i] = $null   # the split fields are kept; release the line
        if ($fields[0] -cne $letter) {
            # an empty or foreign case line (a generator bug): report it and go on, so the failure list is complete
            $failures.Add("${letter}: case line #$i is empty or starts with '$($fields[0])'")
            continue
        }
        $k = if ($i -lt $kotlin.Count) { $kotlin[$i] } else { $null }
        $p = if ($i -lt $port.Count) { $port[$i] } else { $null }
        $rest = [string[]]$(if ($fields.Count -gt 1) { $fields[1..($fields.Count - 1)] } else { @() })
        $cases.Add($rest)
        $answers.Add($k)
        $portAnswers.Add($p)
        if (($null -ne $k -and $k.StartsWith('?')) -or ($null -ne $p -and $p.StartsWith('?'))) { $unknown++ }
        $kc = $k; $pc = $p
        if ($folding) {
            $kc = & $folding.Fold $rest $k
            $pc = & $folding.Fold $rest $p
        }
        if ($kc -cne $pc) {
            $mismatches++
            if ($script:shown -lt 12) {
                $script:shown++
                Write-Output ("MISMATCH #$i [$letter] input: " + (($rest | ForEach-Object { ConvertFrom-Field $_ }) -join ' , '))
                Write-Output "   kotlin: $(ConvertFrom-Answer $k)"
                Write-Output "   port:   $(ConvertFrom-Answer $p)"
            }
        }
    }
    $generated = $null; $kotlin = $null; $port = $null
    if ($mismatches -gt 0) { $failures.Add("${letter}: $mismatches mismatches") }
    if ($unknown -gt 0) { $failures.Add("${letter}: $unknown answers of '?' (a side does not know the case)") }
    if ($cases.Count -eq 0) { $failures.Add("${letter}: no cases") }
    foreach ($message in @(& $Statistics[$letter].Check $cases.ToArray() $answers.ToArray() $portAnswers.ToArray())) { if ($message) { $failures.Add($message) } }
    if ($folding) { Write-Output $folding.Note }
    $summary.Add("${letter}: $($cases.Count) cases, $mismatches mismatches")
}

foreach ($letter in $letters | Where-Object { $Statistics.Contains($_) }) {
    Write-Output "--- $letter ---"
    if ($Statistics[$letter].Table) { Invoke-TableKind $letter } else { Invoke-CaseKind $letter }
    # release the kind's data before the next kind
    [System.GC]::Collect()
    [System.GC]::WaitForPendingFinalizers()
    [System.GC]::Collect()
}

$summary | ForEach-Object { Write-Output $_ }
if ($failures.Count -gt 0) {
    Write-Output 'FAILED:'
    $failures | ForEach-Object { Write-Output "  $_" }
    exit 1
}
Write-Output "PASSED (kinds $($letters -join ''), $PerKind cases per case kind, seed $Seed)"
exit 0
